```python
# products/schemas.py
from datetime import datetime
from decimal import Decimal
from ninja import Schema


class ProductCreateSchema(Schema):
    name: str
    price: Decimal
    description: str | None = None


class ProductUpdateSchema(Schema):
    name: str | None = None
    price: Decimal | None = None
    description: str | None = None


class ProductListItemSchema(Schema):
    id: int
    name: str
    price: Decimal
    created_at: datetime


class ProductDetailSchema(Schema):
    id: int
    name: str
    price: Decimal
    description: str | None
    created_at: datetime
    updated_at: datetime


class ProblemDetailSchema(Schema):
    type: str = "about:blank"
    title: str
    status: int
    detail: str | None = None
    instance: str | None = None
```

```python
# products/router.py
from ninja import Router

from .schemas import (
    ProblemDetailSchema,
    ProductCreateSchema,
    ProductDetailSchema,
    ProductListItemSchema,
    ProductUpdateSchema,
)
from .services import (
    ProductNotFoundError,
    create_product,
    delete_product,
    get_product,
    list_products,
    update_product,
)

router = Router(tags=["products"])


def problem(status: int, title: str, detail: str | None = None) -> ProblemDetailSchema:
    return ProblemDetailSchema(status=status, title=title, detail=detail)


@router.get("/", response={200: list[ProductListItemSchema]})
def product_list(request):
    products = list_products(actor=request.auth)
    return 200, products


@router.get("/{product_id}", response={200: ProductDetailSchema, 404: ProblemDetailSchema})
def product_detail(request, product_id: int):
    try:
        product = get_product(product_id=product_id, actor=request.auth)
    except ProductNotFoundError:
        return 404, problem(404, "Product not found")

    return 200, product


@router.post("/", response={201: ProductDetailSchema, 400: ProblemDetailSchema})
def product_create(request, payload: ProductCreateSchema):
    product = create_product(payload=payload, actor=request.auth)
    return 201, product


@router.patch("/{product_id}", response={200: ProductDetailSchema, 404: ProblemDetailSchema})
def product_update(request, product_id: int, payload: ProductUpdateSchema):
    try:
        product = update_product(product_id=product_id, payload=payload, actor=request.auth)
    except ProductNotFoundError:
        return 404, problem(404, "Product not found")

    return 200, product


@router.delete("/{product_id}", response={204: None, 404: ProblemDetailSchema})
def product_delete(request, product_id: int):
    try:
        delete_product(product_id=product_id, actor=request.auth)
    except ProductNotFoundError:
        return 404, problem(404, "Product not found")

    return 204, None
```

```python
# api.py
from ninja import NinjaAPI

from products.router import router as products_router

api = NinjaAPI(title="Service API")
api.add_router("/products", products_router)
```

